from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework import status
from organizations.models import OrganizationUser

class UpdateOrganizationMemberRoleView(APIView):
    permission_classes = [IsAuthenticated]

    def put(self, request, org_id: int, member_id: int):
        # Verify the requesting user is an administrator of this specific organization
        caller_membership = OrganizationUser.objects.filter(
            organization_id=org_id,
            user=request.user,
            is_admin=True
        ).first()

        if not caller_membership and not request.user.is_superuser:
            return Response({'error': 'Administrator permissions required for this organization'}, status=status.HTTP_403_FORBIDDEN)

        try:
            membership = OrganizationUser.objects.get(id=member_id, organization_id=org_id)
        except OrganizationUser.DoesNotExist:
            return Response({'error': 'Member not found in this organization'}, status=status.HTTP_404_NOT_FOUND)

        is_admin = request.data.get('is_admin', False)
        membership.is_admin = is_admin
        membership.save(update_fields=['is_admin'])

        return Response({
            'member_id': membership.id,
            'is_admin': membership.is_admin,
            'user_id': membership.user_id
        })
